const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bands=[1,2,3,4,5,6,7,8]; let groups=[],state={group:'',pools:[],error:'',detail:null};
const css='<style>.mp{padding:24px;color:var(--text)}.mp h1{color:var(--bright);letter-spacing:.1em}.mpbar,.mpcard,.mpdetail{border:1px solid var(--border);background:linear-gradient(135deg,var(--panel),var(--panel2));padding:16px;margin:14px 0}.mpbar{display:flex;gap:10px;flex-wrap:wrap}.mp input,.mp select,.mp textarea,.mp button{font:inherit;color:var(--text);background:var(--panel2);border:1px solid var(--border);padding:10px}.mp button{cursor:pointer}.mp button.primary{background:var(--accent);color:var(--bg)}.mpgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}.mpresource{border-top:1px solid var(--border);padding:10px 0}.mpmuted{color:var(--muted)}.mpform{display:grid;gap:9px}.mpform label{display:grid;gap:4px;color:var(--muted)}.mpdialog{position:fixed;inset:0;display:grid;place-items:center;background:#000b;z-index:30}.mpdialog>div{width:min(520px,calc(100vw - 30px));padding:20px;border:1px solid var(--accent);background:var(--panel2)}@media(max-width:650px){.mp{padding:14px}}</style>';
const root=()=>document.querySelector('#content'); const request=async(path,opts={})=>{const r=await fetch(path,opts),b=await r.json();if(!r.ok)throw Error(b.error||'Mining data link error');return b};
function render(){const el=root();if(!el||location.hash!=='#miningpool')return;el.innerHTML=css+`<section class=mp><div class=eyebrow>MOBIGLASS SUB-APP / RESOURCE COLLECTION</div><h1>MINING POOLS</h1><div class=mpbar><select id=mpg>${groups.map(g=>`<option value="${esc(g.id)}" ${g.id===state.group?'selected':''}>${esc(g.name)}</option>`).join('')}</select><button id=newmp class=primary>＋ NEW POOL</button></div>${state.error?`<p>${esc(state.error)} <button id=retry>RETRY</button></p>`:''}${state.pools.length?`<div class=mpgrid>${state.pools.map(p=>`<article class=mpcard><div class=eyebrow>${esc(p.status)}</div><h2>${esc(p.name)}</h2><p class=mpmuted>${esc(p.description||'')}</p>${(p.resources||[]).map(r=>`<div class=mpresource><strong>${esc(r.material_name)} / B${r.quality_band}</strong><br>${r.total_scu} / ${r.target_scu??'NO TARGET'} SCU · deposited ${r.deposited_scu}</div>`).join('')}<button data-detail="${p.id}">DETAILS</button></article>`).join('')}</div>`:'<div class=mpcard><strong>NO ACTIVE MINING POOLS</strong><p class=mpmuted>Create a pool to start collecting resources.</p></div>'}</section>`;bind()}
function dialog(title,fields,submit){const el=document.createElement('div');el.className='mpdialog';el.innerHTML=`<div><h2>${title}</h2><form class=mpform>${fields}</form></div>`;root().append(el);const f=el.querySelector('form');f.insertAdjacentHTML('beforeend','<div><button type=button id=mpcancel>CANCEL</button> <button class=primary>SUBMIT</button></div>');el.querySelector('#mpcancel').onclick=()=>el.remove();f.onsubmit=async e=>{e.preventDefault();try{await submit(Object.fromEntries(new FormData(f)));el.remove();await load()}catch(x){alert(x.message)}}}
function bind(){document.querySelector('#mpg')?.addEventListener('change',e=>{state.group=e.target.value;load()});document.querySelector('#retry')?.addEventListener('click',load);document.querySelector('#newmp')?.addEventListener('click',()=>dialog('CREATE MINING POOL','<label>NAME<input name=name required></label><label>DESCRIPTION<textarea name=description></textarea></label>',d=>request('/api/mining-pools',{method:'POST',body:new URLSearchParams({...d,group_id:state.group})})));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>alert('Pool detail is available via the contribution controls in the next pass.'))}
async function load(){if(!state.group)return;state.error='';try{state.pools=(await request('/api/mining-pools?group_id='+state.group)).pools||[]}catch(e){state.error=e.message}render()}
export async function mount(){if(location.hash!=='#miningpool')return;try{groups=(await request('/api/groups')).groups||[];state.group=state.group||groups[0]?.id||'';render();await load()}catch(e){state.error=e.message;render()}} window.addEventListener('hashchange',mount);
const ownerObserver=new MutationObserver(()=>{document.querySelectorAll('.mpcard').forEach((card,index)=>{const pool=state.pools[index];if(pool&&!card.querySelector('.mp-owner'))card.querySelector('h2')?.insertAdjacentHTML('afterend',`<p class="mp-owner mpmuted">OWNER: ${esc(pool.creator_name||'Unknown')}</p>`)});});ownerObserver.observe(document.body,{childList:true,subtree:true});
const enhanceObserver=new MutationObserver(()=>{document.querySelectorAll('.mpcard').forEach((card,index)=>{const pool=state.pools[index];if(!pool||card.querySelector('.mp-extra-actions'))return;card.insertAdjacentHTML('beforeend',`<div class="mp-extra-actions"><button data-resource="${pool.id}">＋ ADD RESOURCE</button><button data-close="${pool.id}" ${pool.status==='closed'?'disabled':''}>CLOSE POOL</button><button data-detail="${pool.id}">DETAILS</button></div>`);card.querySelector('[data-detail]')?.addEventListener('click',()=>showDetail(pool.id));card.querySelector('[data-resource]')?.addEventListener('click',()=>resourceDialog(pool.id));card.querySelector('[data-close]')?.addEventListener('click',async()=>{if(confirm('Close this pool?')){await request(`/api/mining-pools/${pool.id}/close`,{method:'POST'});await load()}})});});enhanceObserver.observe(document.body,{childList:true,subtree:true});
async function resourceDialog(poolId){dialog('ADD RESOURCE TARGET','<label>MATERIAL<input name=material_name required placeholder="Gold"></label><label>QUALITY BAND<select name=quality_band>'+bands.map(b=>`<option value="${b}">B${b}</option>`).join('')+'</select></label><label>TARGET SCU<input name=target_scu type=number min=0 step=0.1 placeholder="optional"></label>',d=>request(`/api/mining-pools/${poolId}/resources`,{method:'POST',body:new URLSearchParams(d)}));}
async function showDetail(poolId){const body=await request(`/api/mining-pools/${poolId}`);const rows=body.pool||[];const first=rows[0];if(!first)return alert('No resources in this pool yet.');const groups=new Map();rows.forEach(r=>{if(!groups.has(r.resource_id))groups.set(r.resource_id,{...r,items:[]});if(r.contribution_id)groups.get(r.resource_id).items.push(r)});const html=[...groups.values()].map(r=>`<div class="mpresource"><strong>${esc(r.material_name)} / B${r.quality_band}</strong><br>Target: ${r.target_scu??'NO TARGET'} SCU${r.items.map(c=>`<div class="mpmuted">${esc(c.contributor_name)} · ${c.quantity_scu} SCU · Q${c.quality_value} · ${String(c.status).toUpperCase()} ${c.status==='reported'?`<button data-deposit="${c.contribution_id}">DEPOSITED</button>`:''}</div>`).join('')}<button data-contribute="${r.resource_id}">＋ CONTRIBUTE</button></div>`).join('');const el=document.createElement('div');el.className='mpdialog';el.innerHTML=`<div><h2>${esc(first.name)} · ${String(first.status).toUpperCase()}</h2><p class=mpmuted>OWNER: ${esc(first.creator_name||'Unknown')}</p>${html}<button id=mpcancel>CLOSE</button></div>`;root().append(el);el.querySelector('#mpcancel').onclick=()=>el.remove();el.querySelectorAll('[data-contribute]').forEach(b=>b.onclick=()=>contributionDialog(b.dataset.contribute,el));el.querySelectorAll('[data-deposit]').forEach(b=>b.onclick=async()=>{await request(`/api/mining-pools/contributions/${b.dataset.deposit}`,{method:'PATCH'});el.remove();showDetail(poolId)})}
function contributionDialog(resourceId,parent){dialog('ADD CONTRIBUTION','<label>QUALITY VALUE<input name=quality_value type=number min=1 max=1000 required placeholder="970"></label><label>QUALITY BAND<select name=quality_band>'+bands.map(b=>`<option value="${b}">B${b}</option>`).join('')+'</select></label><label>QUANTITY SCU<input name=quantity_scu type=number min=0.01 step=0.01 required placeholder="12.4"></label><label>STATUS<select name=status><option value="reported">REPORTED</option><option value="deposited">DEPOSITED</option></select></label><label>SOURCE<input name=source></label><label>NOTE<textarea name=note></textarea></label>',d=>request(`/api/mining-pools/resources/${resourceId}/contributions`,{method:'POST',body:new URLSearchParams(d)}));}
document.addEventListener('click',event=>{const button=event.target.closest('.mpcard [data-detail]');if(button){event.preventDefault();event.stopImmediatePropagation();showDetail(button.dataset.detail)}},true);
const miningMaterials=['Agricium','Aluminum','Aslarite','Beryl','Bexalite','Boron','Borase','Copper','Corundum','Dolivine','Gold','Hadanite','Hephaestanite','Iron','Laranite','Ouratite','Quantainium','Savrilium','Stileron','Taranite','Titanium','Tungsten'];
const qualityRanges={1:[1,399],2:[400,599],3:[600,699],4:[700,799],5:[800,899],6:[900,949],7:[950,998],8:[999,1000]};
const bandOptions=()=>bands.map(b=>`<option value="${b}">B${b} · Quality ${qualityRanges[b][0]}–${qualityRanges[b][1]}</option>`).join('');
function materialResourceDialog(poolId){dialog('ADD RESOURCE TARGET',`<label>MATERIAL<select name="material_name" required><option value="">Select material</option>${miningMaterials.map(m=>`<option>${m}</option>`).join('')}</select></label><label>QUALITY BAND<select name="quality_band">${bandOptions()}</select></label><p class="mpmuted">Bands use the universal Star Citizen quality range 1–1000; material does not change the band limits.</p><label>TARGET SCU<input name="target_scu" type="number" min="0" step="0.1" placeholder="optional"></label>`,d=>request(`/api/mining-pools/${poolId}/resources`,{method:'POST',body:new URLSearchParams(d)}));}
document.addEventListener('click',event=>{const button=event.target.closest('.mpcard [data-resource]');if(button){event.preventDefault();event.stopImmediatePropagation();materialResourceDialog(button.dataset.resource)}},true);
function calculatedContributionDialog(resourceId){dialog('ADD CONTRIBUTION',`<label>QUALITY VALUE<input id="mp-quality" name="quality_value" type="number" min="1" max="1000" required placeholder="970"></label><p id="mp-band" class="mpmuted">QUALITY BAND: enter a value from 1 to 1000</p><input type="hidden" name="quality_band" id="mp-band-value"><label>QUANTITY SCU<input name="quantity_scu" type="number" min="0.01" step="0.01" required placeholder="12.4"></label><label>STATUS<select name="status"><option value="reported">REPORTED</option><option value="deposited">DEPOSITED</option></select></label><label>SOURCE<input name="source"></label><label>NOTE<textarea name="note"></textarea></label>`,d=>request(`/api/mining-pools/resources/${resourceId}/contributions`,{method:'POST',body:new URLSearchParams(d)}));const q=document.querySelector('#mp-quality'),label=document.querySelector('#mp-band'),hidden=document.querySelector('#mp-band-value');q.oninput=()=>{const value=Number(q.value),band=bands.find(b=>value>=qualityRanges[b][0]&&value<=qualityRanges[b][1]);label.textContent=band?`QUALITY BAND: B${band} · Quality ${qualityRanges[band][0]}–${qualityRanges[band][1]}`:'QUALITY BAND: invalid quality';hidden.value=band||'';};}
document.addEventListener('click',event=>{const button=event.target.closest('.mpdialog [data-contribute]');if(button){event.preventDefault();event.stopImmediatePropagation();calculatedContributionDialog(button.dataset.contribute)}},true);
const refineryStations=[['Stanton','ARC-L1 · Refinery'],['Stanton','CRU-L1 · Refinery'],['Stanton','HUR-L1 · Refinery'],['Stanton','HUR-L2 · Refinery'],['Stanton','MIC-L1 · Refinery'],['Stanton','Pyro Gateway (Stanton) · Refinery'],['Nyx','Nyx Gateway · Refinery'],['Pyro','Pyro Gateway · Refinery'],['Pyro','Orbituary Station · Refinery'],['Pyro','Checkmate Station · Refinery'],['Pyro','Ruin Station · Refinery']];
const warehouseOptions='<option value="">Select warehouse</option><optgroup label="Stanton"><option value="Stanton / Hurston / HUR-L1">Stanton / Hurston / HUR-L1</option><option value="Stanton / Hurston / HUR-L2">Stanton / Hurston / HUR-L2</option><option value="Stanton / microTech / MIC-L1">Stanton / microTech / MIC-L1</option><option value="Stanton / ArcCorp / ARC-L1">Stanton / ArcCorp / ARC-L1</option><option value="Stanton / Crusader / CRU-L1">Stanton / Crusader / CRU-L1</option><option value="Stanton / Orbital / Port Tressler">Stanton / Orbital / Port Tressler</option></optgroup><optgroup label="Nyx"><option value="Nyx / Nyx / Nyx Gateway">Nyx / Nyx / Nyx Gateway</option><option value="Nyx / Levski / Levski">Nyx / Levski / Levski</option></optgroup><optgroup label="Pyro"><option value="Pyro / Pyro I / Checkmate Station">Pyro / Pyro I / Checkmate Station</option><option value="Pyro / Pyro V / Orbituary Station">Pyro / Pyro V / Orbituary Station</option><option value="Pyro / Pyro VI / Ruin Station">Pyro / Pyro VI / Ruin Station</option><option value="Pyro / Gateway / Pyro Gateway">Pyro / Gateway / Pyro Gateway</option></optgroup>';
const originalDialog=dialog;dialog=(title,fields,submit)=>{if(!String(title).includes('CONTRIBUTE'))return originalDialog(title,fields,submit);const el=document.createElement('div');el.className='mpdialog';el.innerHTML=`<div><h2>${title}</h2><form class=mpform>${fields.replace(/<label>STATUS[\s\S]*?<\/label>/,'')}<label><input type="checkbox" name="in_refinery" id="in-refinery"> IN REFINERY</label><label id="refinery-station-wrap" hidden>REFINERY STATION<select name="refinery_station">${refineryStations.map(([system,name])=>`<option value="${esc(system+' / '+name)}">${esc(system+' / '+name)}</option>`).join('')}</select></label><label>WAREHOUSE SOURCE<select name="source">${warehouseOptions}</select></label></form></div>`;root().append(el);const f=el.querySelector('form');f.insertAdjacentHTML('beforeend','<div><button type=button id=mpcancel>CANCEL</button> <button class=primary>SUBMIT</button></div>');el.querySelector('#mpcancel').onclick=()=>el.remove();el.querySelector('#in-refinery').onchange=e=>{el.querySelector('#refinery-station-wrap').hidden=!e.target.checked};f.onsubmit=async e=>{e.preventDefault();try{await submit(Object.fromEntries(new FormData(f)));el.remove();await load()}catch(x){alert(x.message)}};};
const trackingObserver=new MutationObserver(()=>{document.querySelectorAll('.mpdialog form input[name="target_scu"]').forEach(input=>input.closest('label')?.remove());document.querySelectorAll('.mpcard').forEach((card,index)=>{const pool=state.pools[index];(pool?.resources||[]).forEach((resource,n)=>{const row=card.querySelectorAll('.mpresource')[n];if(row&&!row.dataset.tracking){row.dataset.tracking='1';row.innerHTML=`<strong>${esc(resource.material_name)} / B${resource.quality_band}</strong><br>${resource.total_scu} SCU collected`;}})});});trackingObserver.observe(document.body,{childList:true,subtree:true});
const contributionButtonsObserver=new MutationObserver(()=>{document.querySelectorAll('.mpcard').forEach((card,index)=>{const pool=state.pools[index],actions=card.querySelector('.mp-extra-actions');if(!pool||!actions||actions.dataset.contributions)return;actions.dataset.contributions='1';actions.querySelector('[data-resource]')?.remove();(pool.resources||[]).forEach(resource=>actions.insertAdjacentHTML('afterbegin',`<button data-direct-contribute="${resource.id}">＋ CONTRIBUTE ${esc(resource.material_name)} / B${resource.quality_band}</button>`));actions.querySelectorAll('[data-direct-contribute]').forEach(button=>button.onclick=()=>calculatedContributionDialog(button.dataset.directContribute));});});contributionButtonsObserver.observe(document.body,{childList:true,subtree:true});
const poolContributionObserver=new MutationObserver(()=>{document.querySelectorAll('.mpcard').forEach((card,index)=>{const pool=state.pools[index],actions=card.querySelector('.mp-extra-actions');if(pool&&actions&&!actions.querySelector('[data-pool-contribute]')){actions.insertAdjacentHTML('afterbegin','<button data-pool-contribute>＋ CONTRIBUTE MATERIAL</button>');actions.querySelector('[data-pool-contribute]').onclick=()=>poolContributionDialog(pool.id);}})});poolContributionObserver.observe(document.body,{childList:true,subtree:true});
function poolContributionDialog(poolId){dialog('CONTRIBUTE MATERIAL',`<label>MATERIAL<select name="material_name" required><option value="">Select material</option>${miningMaterials.map(m=>`<option>${m}</option>`).join('')}</select></label><label>QUALITY VALUE<input id="pool-quality" name="quality_value" type="number" min="1" max="1000" required placeholder="970"></label><p id="pool-band" class="mpmuted">QUALITY BAND: enter a value from 1 to 1000</p><input type="hidden" name="quality_band" id="pool-band-value"><label>QUANTITY SCU<input name="quantity_scu" type="number" min="0.01" step="0.01" required placeholder="12.4"></label><label>STATUS<select name="status"><option value="reported">REPORTED</option><option value="deposited">DEPOSITED</option></select></label><label>SOURCE<input name="source"></label><label>NOTE<textarea name="note"></textarea></label>`,async d=>{const existing=(state.pools.find(p=>p.id===poolId)?.resources||[]).find(r=>r.material_name.toLowerCase()===d.material_name.toLowerCase()&&Number(r.quality_band)===Number(d.quality_band));const resource=existing||await request(`/api/mining-pools/${poolId}/resources`,{method:'POST',body:new URLSearchParams({material_name:d.material_name,quality_band:d.quality_band,target_scu:''})});return request(`/api/mining-pools/resources/${existing?.id||resource.id}/contributions`,{method:'POST',body:new URLSearchParams(d)});});const q=document.querySelector('#pool-quality'),label=document.querySelector('#pool-band'),hidden=document.querySelector('#pool-band-value');q.oninput=()=>{const value=Number(q.value),band=bands.find(b=>value>=qualityRanges[b][0]&&value<=qualityRanges[b][1]);label.textContent=band?`QUALITY BAND: B${band} · Quality ${qualityRanges[band][0]}–${qualityRanges[band][1]}`:'QUALITY BAND: invalid quality';hidden.value=band||'';};}

const matrixCss='<style id="mp-matrix-css">.mp-matrix{padding:24px;color:var(--text)}.mp-matrix h1{color:var(--bright);letter-spacing:.1em}.mp-matrix-bar{display:flex;gap:10px;flex-wrap:wrap;padding:16px;border:1px solid var(--border);background:var(--panel);margin:16px 0}.mp-matrix-bar label{display:grid;gap:5px;color:var(--muted);font-size:11px;letter-spacing:.08em}.mp-matrix select,.mp-matrix button{font:inherit;color:var(--text);background:var(--panel2);border:1px solid var(--border);padding:10px}.mp-matrix button{cursor:pointer}.mp-tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}.mp-tile{min-height:155px;padding:14px;border:1px solid var(--border);background:linear-gradient(145deg,var(--panel),var(--panel2));cursor:pointer;text-align:left;color:var(--text)}.mp-tile:hover,.mp-tile:focus-visible{border-color:var(--accent);box-shadow:0 0 22px var(--glow);outline:1px solid var(--accent)}.mp-tile.empty{opacity:.4}.mp-code{font-size:20px;font-weight:700;color:var(--accent)}.mp-name{margin:16px 0 8px;color:var(--bright);font-weight:700}.mp-scu{font-size:18px}.mp-systems,.mp-bands{margin-top:8px;color:var(--muted);font-size:11px}.mp-detail-table{width:100%;border-collapse:collapse;margin-top:16px}.mp-detail-table th,.mp-detail-table td{padding:9px;border-bottom:1px solid var(--border);text-align:left}.mp-detail-table th{color:var(--accent);font-size:11px}.mp-detail-table td{color:var(--text)}@media(max-width:650px){.mp-matrix{padding:14px}.mp-tiles{grid-template-columns:repeat(2,minmax(0,1fr))}.mp-detail-table{display:block;overflow:auto;white-space:nowrap}}</style>';
const matrixMaterials=()=>miningMaterials.map(name=>({material_name:name,uex_code:{Agricium:'AGRI',Aluminum:'ALUM',Aslarite:'ASLA',Beryl:'BERY',Bexalite:'BEXA',Borase:'BORA',Copper:'COPP',Corundum:'CORU',Gold:'GOLD',Iron:'IRON',Laranite:'LARA',Ouratite:'OURA',Quantainium:'QUAN',Savrilium:'SAVR',Stileron:'STIL',Taranite:'TARA',Titanium:'TITA',Tungsten:'TUNG'}[name]||'ITEM',total_scu:0,systems:{},bands:{},contributors:0,locations:0,pools:0}));
let matrixState={materials:[],pools:[],poolId:'',detail:null};
async function renderMatrix(){const el=root();if(!el||location.hash!=='#miningpool')return;el.innerHTML=matrixCss+`<section class="mp-matrix"><div class="eyebrow">MOBIGLASS RESOURCE MATRIX / UEX MATERIAL INDEX</div><h1>MINING RESOURCE MATRIX</h1><div class="mp-matrix-bar"><label>GROUP<select id="matrix-group">${groups.map(g=>`<option value="${esc(g.id)}" ${g.id===state.group?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><label>POOL<select id="matrix-pool"><option value="">ALL ACTIVE POOLS</option>${matrixState.pools.map(p=>`<option value="${p.id}" ${p.id===matrixState.poolId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><button id="matrix-refresh">REFRESH</button></div>${state.error?`<p class="mpmuted">${esc(state.error)} <button id="matrix-retry">RETRY</button></p>`:''}<div class="mp-tiles">${matrixState.materials.map(m=>`<button class="mp-tile ${m.total_scu?'':'empty'}" data-matrix-material="${esc(m.uex_code)}" title="${esc(m.material_name)}"><div class="mp-code">${esc(m.uex_code)}</div><div class="mp-name">${esc(m.material_name)}</div><div class="mp-scu">${Number(m.total_scu).toFixed(1)} SCU</div><div class="mp-systems">${['Stanton','Pyro','Nyx'].map(s=>m.systems?.[s]?`● ${s.slice(0,3).toUpperCase()}`:`○ ${s.slice(0,3).toUpperCase()}`).join(' ')}</div><div class="mp-bands">${Object.entries(m.bands||{}).map(([b,v])=>`B${b}: ${Number(v).toFixed(1)}`).join(' · ')||'NO DATA'}</div></button>`).join('')}</div></section>`;document.querySelector('#matrix-group').onchange=e=>{state.group=e.target.value;matrixLoad()};document.querySelector('#matrix-pool').onchange=e=>{matrixState.poolId=e.target.value;matrixLoad()};document.querySelector('#matrix-refresh').onclick=matrixLoad;document.querySelector('#matrix-retry')?.addEventListener('click',matrixLoad);document.querySelectorAll('[data-matrix-material]').forEach(b=>{b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openMatrixDetail(b.dataset.matrixMaterial)}};b.onclick=()=>openMatrixDetail(b.dataset.matrixMaterial)});}
async function matrixLoad(){try{state.error='';matrixState.pools=(await request('/api/mining-pools?group_id='+state.group)).pools||[];const body=await request('/api/mining-pools/matrix?group_id='+state.group+(matrixState.poolId?'&pool_id='+encodeURIComponent(matrixState.poolId):''));const byCode=new Map((body.materials||[]).map(m=>[m.uex_code,m]));matrixState.materials=matrixMaterials().map(m=>byCode.get(m.uex_code)||m);await renderMatrix()}catch(e){state.error=e.message;await renderMatrix()}}
